import{_ as a,o as n,c as e,ai as p}from"./chunks/framework.Ba-VnP44.js";const u=JSON.parse('{"title":"03 技术架构设计","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/dev-spec/02-lifecycle/architecture-design.md","filePath":"ai/productivity/dev-spec/02-lifecycle/architecture-design.md"}'),l={name:"ai/productivity/dev-spec/02-lifecycle/architecture-design.md"};function i(r,s,t,c,b,d){return n(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="_03-技术架构设计" tabindex="-1">03 技术架构设计 <a class="header-anchor" href="#_03-技术架构设计" aria-label="Permalink to “03 技术架构设计”">​</a></h1><blockquote><p>第二层 · 开发生命周期。解决「避免 AI 没定方案就动手，写到一半发现方向错了」——复杂任务先出方案、比较取舍、明确修改范围和风险，再进入编码。</p></blockquote><h2 id="什么时候用" tabindex="-1">什么时候用 <a class="header-anchor" href="#什么时候用" aria-label="Permalink to “什么时候用”">​</a></h2><ul><li>L2 普通任务：分析影响后给简要方案。</li><li>L3 复杂任务：完整方案 + 风险清单 + 分阶段计划。</li><li>L1 简单任务：跳过本阶段，直接开发。</li></ul><p><strong>判断标准：如果方案错了要回滚多个文件或改数据结构，就必须先设计。</strong></p><h2 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to “操作步骤”">​</a></h2><h3 id="方案回答五个维度" tabindex="-1">方案回答五个维度 <a class="header-anchor" href="#方案回答五个维度" aria-label="Permalink to “方案回答五个维度”">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>要说明什么</th></tr></thead><tbody><tr><td>数据</td><td>表、索引、约束、迁移、事务</td></tr><tr><td>接口</td><td>路径、入出参、错误码、兼容性</td></tr><tr><td>模块与分层</td><td>落在哪个包、依赖方向</td></tr><tr><td>兼容与影响</td><td>老数据、调用方、开关、定时任务</td></tr><tr><td>验证方式</td><td>哪些测试、哪些命令、哪些人工核对</td></tr></tbody></table><h3 id="多方案比较与取舍" tabindex="-1">多方案比较与取舍 <a class="header-anchor" href="#多方案比较与取舍" aria-label="Permalink to “多方案比较与取舍”">​</a></h3><p>凡有多种做法，给出可选方案并比较：改动范围、数据影响、兼容性、回滚成本、验证难度。</p><p>取舍顺序：<strong>业务正确性 → 兼容性 → 改动范围 → 复用 → 可验证性 → 代码美观</strong>。</p><h3 id="明确修改范围三栏" tabindex="-1">明确修改范围三栏 <a class="header-anchor" href="#明确修改范围三栏" aria-label="Permalink to “明确修改范围三栏”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>允许修改：</span></span>
<span class="line"><span>- backend/.../service/WorkOrderService.java</span></span>
<span class="line"><span>- web/src/api/mes.ts</span></span>
<span class="line"><span></span></span>
<span class="line"><span>禁止修改：</span></span>
<span class="line"><span>- 任何已有接口路径与方法签名</span></span>
<span class="line"><span>- legacy/ 目录下的历史逻辑</span></span>
<span class="line"><span>- pom.xml、package.json（本次不新增依赖）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>必须保持兼容：</span></span>
<span class="line"><span>- GET /api/mes/work-orders 的返回结构</span></span>
<span class="line"><span>- 现有状态机的流转规则</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>同时写出「本次不做项」——防止 AI 按自己的理解顺手扩大范围。</p><h3 id="风险清单与拆解" tabindex="-1">风险清单与拆解 <a class="header-anchor" href="#风险清单与拆解" aria-label="Permalink to “风险清单与拆解”">​</a></h3><p>风险写成「风险 → 触发条件 → 影响 → 处理 → 谁确认」，不写「可能有风险」这种执行时不知道怎么处理的话。</p><p>方案通过后拆成子任务：能独立完成、能独立验收、一次提交能覆盖。按依赖顺序排：<code>数据层 → 后端服务 → 接口层 → 前端 → 测试 → 文档</code>。前后端并行有前提——接口契约先冻结。</p><p>子任务完成标准写成命令、diff 特征或页面行为，不写「完成开发」。</p><h2 id="可复制提示词" tabindex="-1">可复制提示词 <a class="header-anchor" href="#可复制提示词" aria-label="Permalink to “可复制提示词”">​</a></h2><details><summary><strong>生成技术方案（本轮不改代码）</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>你的任务只有一个：基于已有上下文产出技术方案和风险清单。本轮不要改代码、不要建文件。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>任务：&lt;一句话&gt;</span></span>
<span class="line"><span>已有上下文：涉及模块与文件、相关调用链、数据库与接口现状、已知约束与禁改区。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>按以下结构输出：</span></span>
<span class="line"><span>1. 需求复述（三句话内）</span></span>
<span class="line"><span>2. 仍模糊且会影响实现的问题（按影响排序）</span></span>
<span class="line"><span>3. 本次不做项</span></span>
<span class="line"><span>4. 方案比较（给出可选方案，逐项对比改动范围、数据影响、兼容性、回滚成本、验证难度）</span></span>
<span class="line"><span>5. 推荐方案与理由（按业务正确性 → 兼容性 → 改动范围 → 复用 → 可验证性排序）</span></span>
<span class="line"><span>6. 修改范围三栏（允许修改 / 禁止修改 / 必须保持兼容）</span></span>
<span class="line"><span>7. 风险清单（风险 → 触发条件 → 影响 → 处理 → 谁确认）</span></span>
<span class="line"><span>8. 子任务拆解（编号 | 任务 | 涉及文件 | 依赖 | 完成标准 | 验收方式）</span></span>
<span class="line"><span>9. 执行顺序与检查点</span></span>
<span class="line"><span>10. 需要我拍板的问题（没有就写「无，可以开始」）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不要输出实现代码；不要编造项目里不存在的组件或服务；无法判断的标「待确认」。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div></details><details><summary><strong>表结构与接口契约评审</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请评审下面这次涉及的数据结构和接口契约，本轮只评审，不改代码。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>表结构变更：&lt;粘贴 DDL 或字段说明&gt;</span></span>
<span class="line"><span>接口变更：&lt;路径、入参、出参、错误码&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请检查：</span></span>
<span class="line"><span>1. 字段类型、长度、非空约束、索引是否合理，是否影响已有数据。</span></span>
<span class="line"><span>2. 迁移脚本能否重复执行，回滚是否可行。</span></span>
<span class="line"><span>3. 接口入出参是否兼容已有调用方，错误码是否完整。</span></span>
<span class="line"><span>4. 是否有幂等、并发、租户、权限方面的遗漏。</span></span>
<span class="line"><span>5. 前端契约与后端 DTO 是否一致。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每条问题给「问题 → 影响 → 建议」，并标严重程度。没问题的项也明确写「已检查，无问题」。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div></details><h2 id="验收要点" tabindex="-1">验收要点 <a class="header-anchor" href="#验收要点" aria-label="Permalink to “验收要点”">​</a></h2><ul><li>[ ] 方案覆盖数据、接口、模块、兼容、验证五个维度。</li><li>[ ] 写出本次不做项和修改范围三栏，落到具体文件路径。</li><li>[ ] 多方案有比较，取舍理由符合优先级。</li><li>[ ] 风险清单每条有处理动作和确认人。</li><li>[ ] 子任务能独立执行、独立验收，完成标准可核对。</li><li>[ ] 需要人拍板的事项已拍板；没有编造不存在的组件。</li></ul><p>方案通过进入 <a href="/my-vitepress-site/ai/productivity/dev-spec/02-lifecycle/development.html">04 功能开发</a>。接口与数据的变更控制按第三层 <a href="/my-vitepress-site/ai/productivity/dev-spec/03-quality/change-control.html">变更控制</a> 执行。</p>`,24)])])}const m=a(l,[["render",i]]);export{u as __pageData,m as default};
